import "server-only";
import raw from "../../../prisma/seed-data/credits.json";

/**
 * Image credits (prisma/seed-data/credits.json, generated by the data pipeline). CC BY / CC BY-SA require
 * attribution with a licence link and a note that the work was modified — /credits renders all of it.
 * Read once at module scope (static file, same for every request).
 */

export type Credit = {
  url: string;
  kind: "product" | "lifestyle";
  title: string;
  alt: string;
  source: string;
  sourceUrl: string | null;
  creator: string;
  license: string;
  licenseUrl: string | null;
  attribution: string;
  usedFor: string[];
};

export type CreditsData = {
  modifications: { product: string; lifestyle: string };
  sources: { name: string; url: string | null }[];
  licenses: { name: string; url: string | null; count: number }[];
  product: Credit[];
  lifestyle: Credit[];
  total: number;
};

const safeUrl = (u: unknown): string | null => (typeof u === "string" && /^https?:\/\//i.test(u) ? u : null);
const str = (u: unknown, max = 400) => (typeof u === "string" ? u.slice(0, max) : "");

type RawFile = {
  modifications?: Record<string, unknown>;
  sources?: Record<string, unknown>;
  licenses?: Record<string, { url?: unknown; count?: unknown }>;
  images?: Record<string, unknown>[];
};

function build(): CreditsData {
  const f = raw as unknown as RawFile;
  const images: Credit[] = (f.images ?? [])
    .map((i) => ({
      url: str(i.url),
      kind: (i.kind === "product" ? "product" : "lifestyle") as Credit["kind"],
      title: str(i.title),
      alt: str(i.alt),
      source: str(i.source, 80),
      sourceUrl: safeUrl(i.sourceUrl),
      creator: str(i.creator, 160),
      license: str(i.license, 40),
      licenseUrl: safeUrl(i.licenseUrl),
      attribution: str(i.attribution, 500),
      usedFor: Array.isArray(i.usedFor) ? i.usedFor.map((u) => str(u, 120)).filter(Boolean).slice(0, 8) : [],
    }))
    .filter((i) => i.url.startsWith("/"));
  const byTitle = (a: Credit, b: Credit) => a.title.localeCompare(b.title);
  return {
    modifications: { product: str(f.modifications?.product, 800), lifestyle: str(f.modifications?.lifestyle, 800) },
    sources: Object.entries(f.sources ?? {}).map(([name, url]) => ({ name, url: safeUrl(url) })),
    licenses: Object.entries(f.licenses ?? {}).map(([name, v]) => ({ name, url: safeUrl(v?.url), count: Number(v?.count) || 0 })),
    product: images.filter((i) => i.kind === "product").sort(byTitle),
    lifestyle: images.filter((i) => i.kind === "lifestyle").sort(byTitle),
    total: images.length,
  };
}

const DATA = build();

export function getCredits(): CreditsData {
  return DATA;
}
